using System;using System.Collections.Generic;public class Solution{public bool IsRectangleCover(int[][]r){long area=0;int x1=int.MaxValue,y1=int.MaxValue,x2=int.MinValue,y2=int.MinValue;var s=new HashSet<string>();foreach(var a in r){x1=Math.Min(x1,a[0]);y1=Math.Min(y1,a[1]);x2=Math.Max(x2,a[2]);y2=Math.Max(y2,a[3]);area+=(long)(a[2]-a[0])*(a[3]-a[1]);foreach(string q in new[]{$"{a[0]},{a[1]}",$"{a[0]},{a[3]}",$"{a[2]},{a[1]}",$"{a[2]},{a[3]}"})if(!s.Add(q))s.Remove(q);}return area==(long)(x2-x1)*(y2-y1)&&s.SetEquals(new[]{$"{x1},{y1}",$"{x1},{y2}",$"{x2},{y1}",$"{x2},{y2}"});}}
